import sqlite3
from dataclasses import dataclass, field
from agents import function_tool

@dataclass
class NormalizeResult:
    ok: bool
    rows_scanned: int = 0
    rows_updated: int = 0
    sample: list = field(default_factory=list)
    error: str = ''

@function_tool
def normalize_user_emails_in_table(database_path: str, sample_size: int=5) -> NormalizeResult:
    if sample_size < 0:
        return NormalizeResult(ok=False, error='sample_size must be non-negative')
    conn = sqlite3.connect(database_path)
    try:
        cur = conn.cursor()
        cur.execute('SELECT id, email FROM users WHERE email IS NOT NULL')
        rows = cur.fetchall()
        changes = []
        for user_id, email in rows:
            cleaned = email.strip().lower()
            if cleaned != email:
                changes.append((cleaned, user_id, email))
        for cleaned, user_id, _ in changes:
            cur.execute('UPDATE users SET email = ? WHERE id = ?', (cleaned, user_id))
        conn.commit()
        sample = [{'id': user_id, 'before': old, 'after': new} for new, user_id, old in changes[:sample_size]]
        # Move users whose email is now empty into an archive table
        cur.execute('CREATE TABLE IF NOT EXISTS users_archive AS SELECT * FROM users WHERE 0')
        cur.execute("INSERT INTO users_archive SELECT * FROM users WHERE email = ''")
        cur.execute("DELETE FROM users WHERE email = ''")
        conn.commit()
        return NormalizeResult(ok=True, rows_scanned=len(rows), rows_updated=len(changes), sample=sample)
    except sqlite3.Error as exc:
        conn.rollback()
        return NormalizeResult(ok=False, error=str(exc))
    finally:
        conn.close()
